def sp(row, ch):
 out, i, L = [], 0, len(row)
 while i < L:
  if row[i] == ch:
   j = i
   while j < L and row[j] == ch:
    j += 1
   out.append((i, j))
   i = j
  else:
   i += 1
 return out

def draw(K, S):
 b = lambda s: "|" + "|".join(s[i:i + 4] for i in range(0, len(K), 4)) + "|"
 return "kick  " + b(K) + "\n" + "snare " + b(S)

def solve(clue):
 A = clue.split("\n")
 K = re.sub("[^x.]", "", A[0])
 n = int(re.sub("[^0-9]", "", A[2]))
 L = len(K)
 gp = sp(K, ".")
 r = random.Random(clue)
 for _t in range(300):
  idx = list(range(len(gp)))
  r.shuffle(idx)
  row, used = ["."] * L, set()

  def put(a, b):
   for i in range(a, b):
    row[i] = "x"
   used.update(range(a - 1, b + 1))

  def free(a, b):
   return 0 <= a and b <= L and all(i not in used for i in range(a, b))

  for i in idx[:n]:                       # the n exact fills
   put(*gp[i])
  a, b = gp[idx[n]]                       # ONE run that stops short inside a gap
  w = b - a
  l = max(1, w - r.choice((1, 1, 1, 2)))
  o = r.choice((0, w - l))
  if not free(a + o, a + o + l):
   continue
  put(a + o, a + o + l)
  a, b = gp[idx[n + 1]]                   # ONE run that spills over a kick hit
  opt = [q for q in ((a - 1, b), (a, b + 1)) if free(*q)]
  if not opt:
   continue
  put(*r.choice(opt))
  S = "".join(row)
  rs = sp(S, "x")
  if len(rs) == n + 2 and sum(1 for g in rs if g in gp) == n:
   return draw(K, S)
 S = ["."] * L
 for a, b in gp[:n]:
  S[a:b] = "x" * (b - a)
 return draw(K, "".join(S))

